def search_videos(query, region=None, language=None, published_after=None, published_before=None, channel_id=None, category_id=None, sort=None, safe_search=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0205000" if __import__("os").path.isdir("./environment_mix/0205000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)

    TTL_HOURS = 6

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt_opt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "__INVALID__"
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return "__INVALID__"

    def _norm_region(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "__INVALID__"
        v = s.strip()
        if not v:
            return None
        if not re.fullmatch(r"[A-Za-z]{2}", v):
            return "__INVALID__"
        return v.upper()

    def _norm_lang(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "__INVALID__"
        v = s.strip()
        if not v:
            return None
        if not (2 <= len(v) <= 16) or not re.fullmatch(r"[A-Za-z0-9-]+", v):
            return "__INVALID__"
        return v

    def _stable_fingerprint(obj):
        def _norm(x):
            if isinstance(x, dict):
                return {k: _norm(x[k]) for k in sorted(x)}
            if isinstance(x, list):
                return [_norm(v) for v in x]
            if isinstance(x, float):
                return float(f"{x:.6f}")
            if isinstance(x, datetime.datetime):
                return x.replace(microsecond=0).isoformat() + "Z"
            return x
        b = json.dumps(_norm(obj), sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24]}"

    def _pick_active_client(clients):
        actives = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not actives:
            return None
        def _parse_iso(s):
            if not isinstance(s, str) or not s:
                return None
            try:
                ss = s
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is not None:
                    dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
                return dt
            except Exception:
                return None
        actives.sort(key=lambda c: _parse_iso(c.get("last_used_at")) or datetime.datetime.min, reverse=True)
        return actives[0]

    def _count_today(runs, client_id):
        day = now.strftime("%Y-%m-%d")
        reqs = 0
        units = 0
        for r in runs:
            if r.get("client_id") != client_id:
                continue
            ca = r.get("created_at")
            if not isinstance(ca, str) or len(ca) < 10 or ca[:10] != day:
                continue
            reqs += 1
            try:
                units += max(0, int(r.get("youtube_units_used") or 0))
            except Exception:
                pass
        return reqs, units

    # Resolve ambient auth context
    api_clients = _load("api_clients.json")
    client = _pick_active_client(api_clients)
    if not client:
        return _err("UNAUTHORIZED", "No active API client available for this request.")

    # Validate inputs
    if not isinstance(query, str) or not query.strip():
        # still log query run
        query_runs = _load("query_runs.json")
        qid = _new_id("ytqr")
        params = {"query": query, "region": region, "language": language, "published_after": published_after, "published_before": published_before,
                  "channel_id": channel_id, "category_id": category_id, "sort": sort, "safe_search": safe_search, "limit": limit, "cursor": cursor,
                  "normalized": {}}
        query_runs.append({
            "id": qid, "client_id": client["id"], "tool_name": "search-videos", "status": "failed",
            "request_fingerprint": _stable_fingerprint({"tool": "search-videos", "params": params}),
            "parameters": params, "response_ref": None, "youtube_units_used": 0, "cache_hit": False,
            "error_message": "validation_error_query_required",
            "started_at": None, "finished_at": _now_iso(), "created_at": _now_iso(), "updated_at": _now_iso()
        })
        _save("query_runs.json", query_runs)
        return _err("VALIDATION_ERROR", "query is required")

    query_n = query.strip()
    region_n = _norm_region(region)
    if region_n == "__INVALID__":
        return _err("VALIDATION_ERROR", "region must be a 2-letter ISO code")
    language_n = _norm_lang(language)
    if language_n == "__INVALID__":
        return _err("VALIDATION_ERROR", "language must be 2-16 chars matching [A-Za-z0-9-]+")

    pa = _parse_dt_opt(published_after, "published_after")
    if pa == "__INVALID__":
        return _err("VALIDATION_ERROR", "published_after must be an ISO-8601 date-time string")
    pb = _parse_dt_opt(published_before, "published_before")
    if pb == "__INVALID__":
        return _err("VALIDATION_ERROR", "published_before must be an ISO-8601 date-time string")
    if pa and pb and isinstance(pa, datetime.datetime) and isinstance(pb, datetime.datetime) and pa > pb:
        return _err("VALIDATION_ERROR", "published_after must be <= published_before")

    if channel_id is not None and (not isinstance(channel_id, str) or not channel_id.strip()):
        return _err("VALIDATION_ERROR", "channel_id must be a non-empty string when provided")
    channel_id_n = channel_id.strip() if isinstance(channel_id, str) else None

    if category_id is not None and (not isinstance(category_id, str) or not category_id.strip()):
        return _err("VALIDATION_ERROR", "category_id must be a non-empty string when provided")
    category_id_n = category_id.strip() if isinstance(category_id, str) else None

    if sort is not None:
        if not isinstance(sort, str) or sort not in ("relevance", "date", "view_count", "rating"):
            return _err("VALIDATION_ERROR", "sort must be one of: relevance, date, view_count, rating")
    sort_n = sort or "relevance"

    if safe_search is not None:
        if not isinstance(safe_search, str) or safe_search not in ("none", "moderate", "strict"):
            return _err("VALIDATION_ERROR", "safe_search must be one of: none, moderate, strict")
    safe_search_n = safe_search or "moderate"

    if limit is None:
        limit_n = 20
    else:
        # be tolerant to whole-number floats (some callers serialize numbers as float)
        if isinstance(limit, float) and limit.is_integer():
            limit = int(limit)
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 50:
            return _err("VALIDATION_ERROR", "limit must be within [1, 50]")
        limit_n = limit

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
    cursor_n = cursor.strip() if isinstance(cursor, str) else None

    # Load runs for quota + caching
    query_runs = _load("query_runs.json")

    # Create queued query_run
    normalized = {
        "query": query_n,
        "region": region_n,
        "language": language_n,
        "published_after": pa.replace(microsecond=0).isoformat() + "Z" if isinstance(pa, datetime.datetime) else None,
        "published_before": pb.replace(microsecond=0).isoformat() + "Z" if isinstance(pb, datetime.datetime) else None,
        "channel_id": channel_id_n,
        "category_id": category_id_n,
        "sort": sort_n,
        "safe_search": safe_search_n,
        "limit": limit_n,
        "cursor": cursor_n,
    }
    params = {"query": query, "region": region, "language": language, "published_after": published_after, "published_before": published_before,
              "channel_id": channel_id, "category_id": category_id, "sort": sort, "safe_search": safe_search, "limit": limit, "cursor": cursor,
              "normalized": normalized}
    fingerprint = _stable_fingerprint({"tool": "search-videos", "params": normalized})

    qid = _new_id("ytqr")
    qr = {
        "id": qid,
        "client_id": client["id"],
        "tool_name": "search-videos",
        "status": "queued",
        "request_fingerprint": fingerprint,
        "parameters": params,
        "response_ref": None,
        "youtube_units_used": 0,
        "cache_hit": False,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    query_runs.append(qr)
    _save("query_runs.json", query_runs)

    # Enforce client status (must be active)
    if client.get("status") != "active":
        qr["status"] = "failed"
        qr["error_message"] = "client_not_active"
        qr["finished_at"] = _now_iso()
        qr["updated_at"] = _now_iso()
        _save("query_runs.json", query_runs)
        return _err("UNAUTHORIZED", "client_not_active")

    # Quota check (requests/day)
    reqs_today, units_today = _count_today(query_runs, client["id"])
    daily_req_quota = int(client.get("daily_request_quota") or 0)
    daily_units_quota = int(client.get("daily_youtube_units_quota") or 0)
    if daily_req_quota >= 0 and reqs_today > daily_req_quota:
        qr["status"] = "failed"
        qr["error_message"] = "quota_exceeded_requests_daily"
        qr["finished_at"] = _now_iso()
        qr["updated_at"] = _now_iso()
        _save("query_runs.json", query_runs)
        return _err("QUOTA_EXCEEDED", "daily_request_quota exceeded")

    # Move to running
    qr["status"] = "running"
    qr["started_at"] = _now_iso()
    qr["updated_at"] = _now_iso()
    _save("query_runs.json", query_runs)

    # Cache: succeeded run within 24h for same (client, tool, fingerprint)
    cutoff = now - datetime.timedelta(hours=24)
    def _parse_iso_naive(s):
        if not isinstance(s, str):
            return None
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    cached = None
    for r in query_runs:
        if r.get("client_id") == client["id"] and r.get("tool_name") == "search-videos" and r.get("status") == "succeeded" and r.get("request_fingerprint") == fingerprint:
            fa = _parse_iso_naive(r.get("finished_at"))
            if fa and fa > cutoff:
                cached = r
                break

    videos_rows = _load("videos.json")
    channels_rows = _load("channels.json")

    def _video_matches(v):
        if not isinstance(v, dict):
            return False
        if v.get("status") in ("deleted",):
            return False
        # query match against title/description
        ql = query_n.lower()
        title = (v.get("title") or "")
        desc = (v.get("description") or "")
        if ql not in str(title).lower() and ql not in str(desc).lower():
            return False
        if category_id_n and str(v.get("category_id") or "") != category_id_n:
            return False
        if pa or pb:
            pdt = _parse_iso_naive(v.get("published_at")) if isinstance(v.get("published_at"), str) else None
            if pa and (not pdt or pdt < pa):
                return False
            if pb and (not pdt or pdt > pb):
                return False
        if channel_id_n:
            # channel_id_n is external youtube channel id; videos store internal channel_id FK
            ch = next((c for c in channels_rows if c.get("id") == v.get("channel_id")), None)
            if not ch or ch.get("youtube_channel_id") != channel_id_n:
                return False
        return True

    def _sort_key(v):
        if sort_n == "date":
            dt = _parse_iso_naive(v.get("published_at")) if isinstance(v.get("published_at"), str) else None
            return (dt or datetime.datetime.min)
        if sort_n == "view_count":
            return int(v.get("view_count") or 0)
        if sort_n == "rating":
            # no rating in schema; approximate with like_count
            return int(v.get("like_count") or 0)
        # relevance: keep stable but bump by query occurrences
        ql = query_n.lower()
        t = (v.get("title") or "")
        d = (v.get("description") or "")
        score = str(t).lower().count(ql) * 2 + str(d).lower().count(ql)
        return score

    matched = [v for v in videos_rows if _video_matches(v)]

    reverse = True
    if sort_n == "date":
        reverse = True
    if sort_n in ("view_count", "rating", "relevance"):
        reverse = True

    matched.sort(key=_sort_key, reverse=reverse)

    start = 0
    if cursor_n:
        try:
            if cursor_n.startswith("offset:"):
                start = max(0, int(cursor_n.split(":", 1)[1]))
            else:
                start = max(0, int(cursor_n))
        except Exception:
            start = 0

    page = matched[start:start + limit_n]
    next_cursor = None
    if start + limit_n < len(matched):
        next_cursor = f"offset:{start + limit_n}"

    # Prepare response objects
    def _video_out(v):
        ch = next((c for c in channels_rows if c.get("id") == v.get("channel_id")), None)
        return {
            "id": v.get("youtube_video_id"),
            "internal_id": v.get("id"),
            "title": v.get("title"),
            "description": v.get("description"),
            "published_at": v.get("published_at"),
            "duration_seconds": v.get("duration_seconds"),
            "thumbnail_url": v.get("thumbnail_url"),
            "channel": {
                "id": ch.get("youtube_channel_id") if ch else None,
                "internal_id": ch.get("id") if ch else None,
                "title": ch.get("title") if ch else None,
                "handle": ch.get("handle") if ch else None,
                "country": ch.get("country") if ch else None,
            },
            "stats": {
                "view_count": v.get("view_count"),
                "like_count": v.get("like_count"),
                "comment_count": v.get("comment_count"),
                "as_of": v.get("stats_as_of"),
            },
            "default_language": v.get("default_language"),
            "category_id": v.get("category_id"),
            "status": v.get("status"),
        }

    response_videos = [_video_out(v) for v in page]
    response_ref = {"videos": [v.get("id") for v in page]}

    # If cached exists, mark cache_hit but still return same computed data (store is local)
    youtube_units_used = 5  # nominal search cost
    if daily_units_quota >= 0 and units_today + youtube_units_used > daily_units_quota:
        qr["status"] = "failed"
        qr["error_message"] = "quota_exceeded_youtube_units_daily"
        qr["youtube_units_used"] = 0
        qr["cache_hit"] = False
        qr["finished_at"] = _now_iso()
        qr["updated_at"] = _now_iso()
        _save("query_runs.json", query_runs)
        return _err("QUOTA_EXCEEDED", "daily_youtube_units_quota exceeded")

    qr["status"] = "succeeded"
    qr["youtube_units_used"] = youtube_units_used
    qr["cache_hit"] = bool(cached)
    qr["response_ref"] = response_ref
    qr["finished_at"] = _now_iso()
    qr["updated_at"] = _now_iso()
    _save("query_runs.json", query_runs)

    # update client last_used_at
    for c in api_clients:
        if c.get("id") == client.get("id"):
            c["last_used_at"] = _now_iso()
            c["updated_at"] = _now_iso()
            break
    _save("api_clients.json", api_clients)

    return {
        "videos": response_videos,
        "page": {
            "total": len(matched),
            "limit": limit_n,
            "cursor": cursor_n,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None
        },
        "query_run_id": qid,
        "latency_ms": int((time.time() - t0) * 1000)
    }

def get_video_comments(video_id, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0205000" if __import__("os").path.isdir("./environment_mix/0205000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _stable_fingerprint(obj):
        b = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24]}"

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _pick_active_client(clients):
        actives = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not actives:
            return None
        actives.sort(key=lambda c: _parse_iso(c.get("last_used_at")) or datetime.datetime.min, reverse=True)
        return actives[0]

    def _count_today(runs, client_id):
        day = now.strftime("%Y-%m-%d")
        reqs = 0
        units = 0
        for r in runs:
            if r.get("client_id") != client_id:
                continue
            ca = r.get("created_at")
            if not isinstance(ca, str) or len(ca) < 10 or ca[:10] != day:
                continue
            reqs += 1
            try:
                units += max(0, int(r.get("youtube_units_used") or 0))
            except Exception:
                pass
        return reqs, units

    api_clients = _load("api_clients.json")
    client = _pick_active_client(api_clients)
    if not client:
        return _err("UNAUTHORIZED", "No active API client available for this request.")

    # Validate inputs (tolerate integer-like floats for limit)
    if not isinstance(video_id, str) or not video_id.strip():
        # log failed run
        query_runs = _load("query_runs.json")
        qid = _new_id("ytqr")
        params = {"video_id": video_id, "order": order, "limit": limit, "cursor": cursor, "normalized": {}}
        query_runs.append({
            "id": qid, "client_id": client["id"], "tool_name": "get-video-comments", "status": "failed",
            "request_fingerprint": _stable_fingerprint({"tool": "get-video-comments", "params": params}),
            "parameters": params, "response_ref": None, "youtube_units_used": 0, "cache_hit": False,
            "error_message": "validation_error_video_id_required",
            "started_at": None, "finished_at": _now_iso(), "created_at": _now_iso(), "updated_at": _now_iso()
        })
        _save("query_runs.json", query_runs)
        return _err("VALIDATION_ERROR", "video_id is required")

    video_id_n = video_id.strip()

    if order is None:
        order_n = "time"
    else:
        if not isinstance(order, str) or order not in ("time", "relevance"):
            return _err("VALIDATION_ERROR", "order must be one of: time, relevance")
        order_n = order

    if limit is None:
        limit_n = 20
    else:
        if isinstance(limit, float) and limit.is_integer():
            limit = int(limit)
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be within [1, 100]")
        limit_n = limit

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
    cursor_n = cursor.strip() if isinstance(cursor, str) else None

    query_runs = _load("query_runs.json")

    normalized = {"video_id": video_id_n, "order": order_n, "limit": limit_n, "cursor": cursor_n}
    fingerprint = _stable_fingerprint({"tool": "get-video-comments", "params": normalized})
    qid = _new_id("ytqr")
    qr = {
        "id": qid,
        "client_id": client["id"],
        "tool_name": "get-video-comments",
        "status": "queued",
        "request_fingerprint": fingerprint,
        "parameters": {"video_id": video_id, "order": order, "limit": limit, "cursor": cursor, "normalized": normalized},
        "response_ref": None,
        "youtube_units_used": 0,
        "cache_hit": False,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    query_runs.append(qr)
    _save("query_runs.json", query_runs)

    if client.get("status") != "active":
        qr["status"] = "failed"
        qr["error_message"] = "client_not_active"
        qr["finished_at"] = _now_iso()
        qr["updated_at"] = _now_iso()
        _save("query_runs.json", query_runs)
        return _err("UNAUTHORIZED", "client_not_active")

    reqs_today, units_today = _count_today(query_runs, client["id"])
    daily_req_quota = int(client.get("daily_request_quota") or 0)
    daily_units_quota = int(client.get("daily_youtube_units_quota") or 0)
    if daily_req_quota >= 0 and reqs_today > daily_req_quota:
        qr["status"] = "failed"
        qr["error_message"] = "quota_exceeded_requests_daily"
        qr["finished_at"] = _now_iso()
        qr["updated_at"] = _now_iso()
        _save("query_runs.json", query_runs)
        return _err("QUOTA_EXCEEDED", "daily_request_quota exceeded")

    qr["status"] = "running"
    qr["started_at"] = _now_iso()
    qr["updated_at"] = _now_iso()
    _save("query_runs.json", query_runs)

    videos = _load("videos.json")
    vrow = next((v for v in videos if v.get("youtube_video_id") == video_id_n or v.get("id") == video_id_n), None)
    if not vrow:
        qr["status"] = "failed"
        qr["error_message"] = "video_not_found"
        qr["finished_at"] = _now_iso()
        qr["updated_at"] = _now_iso()
        _save("query_runs.json", query_runs)
        return _err("NOT_FOUND", "video not found")

    assets = _load("video_text_assets.json")
    vid_internal = vrow.get("id")

    # locate latest ready snapshot
    snapshots = [a for a in assets if a.get("video_id") == vid_internal and a.get("asset_type") == "comments_snapshot" and a.get("status") == "ready"]
    snapshots.sort(key=lambda a: int(a.get("version") or 0), reverse=True)
    snap = snapshots[0] if snapshots else None

    # If cursor provided, treat as requesting a "new page" -> create a new snapshot version (business rule)
    if cursor_n:
        # increment version and store provided cursor as nextPageToken (simulating upstream pagination)
        next_ver = 1
        if snapshots:
            next_ver = int(snapshots[0].get("version") or 1) + 1
        # simple deterministic pseudo comments to keep stable-ish
        payload = {"comments": [], "nextPageToken": None}
        prev_token = cursor_n
        payload["nextPageToken"] = None  # end by default
        base_idx = (next_ver - 1) * 1000
        for i in range(limit_n):
            payload["comments"].append({
                "id": f"c_{vid_internal}_{base_idx+i}",
                "text": f"Cached comment {base_idx+i} for video {video_id_n}",
                "author": {"name": "cached_user"},
                "published_at": _now_iso(),
                "like_count": (base_idx + i) % 50
            })
        new_asset = {
            "id": _new_id("ytta"),
            "video_id": vid_internal,
            "asset_type": "comments_snapshot",
            "language": None,
            "source": "youtube_api",
            "status": "ready",
            "version": next_ver,
            "expires_at": None,
            "payload": payload,
            "error_message": None,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        assets.append(new_asset)
        _save("video_text_assets.json", assets)
        snap = new_asset
        cache_hit = False
        youtube_units_used = 2
    else:
        if not snap:
            # create initial snapshot
            payload = {"comments": [], "nextPageToken": "page:2"}
            for i in range(limit_n):
                payload["comments"].append({
                    "id": f"c_{vid_internal}_{i}",
                    "text": f"Cached comment {i} for video {video_id_n}",
                    "author": {"name": "cached_user"},
                    "published_at": _now_iso(),
                    "like_count": i % 50
                })
            new_asset = {
                "id": _new_id("ytta"),
                "video_id": vid_internal,
                "asset_type": "comments_snapshot",
                "language": None,
                "source": "youtube_api",
                "status": "ready",
                "version": 1,
                "expires_at": None,
                "payload": payload,
                "error_message": None,
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            assets.append(new_asset)
            _save("video_text_assets.json", assets)
            snap = new_asset
            cache_hit = False
            youtube_units_used = 2
        else:
            cache_hit = True
            youtube_units_used = 0

    if daily_units_quota >= 0 and units_today + youtube_units_used > daily_units_quota:
        qr["status"] = "failed"
        qr["error_message"] = "quota_exceeded_youtube_units_daily"
        qr["youtube_units_used"] = 0
        qr["cache_hit"] = False
        qr["finished_at"] = _now_iso()
        qr["updated_at"] = _now_iso()
        _save("query_runs.json", query_runs)
        return _err("QUOTA_EXCEEDED", "daily_youtube_units_quota exceeded")

    # paginate within snapshot payload
    comments = (snap.get("payload") or {}).get("comments") or []
    start = 0
    # allow offset cursors too
    if cursor_n and cursor_n.startswith("offset:"):
        try:
            start = max(0, int(cursor_n.split(":", 1)[1]))
        except Exception:
            start = 0
    page = comments[start:start + limit_n]
    next_cursor = None
    has_more = False
    if start + limit_n < len(comments):
        next_cursor = f"offset:{start + limit_n}"
        has_more = True
    else:
        # if snapshot includes nextPageToken, return it as cursor
        npt = (snap.get("payload") or {}).get("nextPageToken")
        if npt:
            next_cursor = str(npt)
            has_more = True

    qr["status"] = "succeeded"
    qr["youtube_units_used"] = youtube_units_used
    qr["cache_hit"] = cache_hit
    qr["response_ref"] = {"assets": [snap.get("id")], "video": vid_internal}
    qr["finished_at"] = _now_iso()
    qr["updated_at"] = _now_iso()
    _save("query_runs.json", query_runs)

    for c in api_clients:
        if c.get("id") == client.get("id"):
            c["last_used_at"] = _now_iso()
            c["updated_at"] = _now_iso()
            break
    _save("api_clients.json", api_clients)

    return {
        "video_id": video_id_n,
        "order": order_n,
        "comments": page,
        "page": {
            "limit": limit_n,
            "cursor": cursor_n,
            "next_cursor": next_cursor,
            "has_more": bool(has_more)
        },
        "snapshot": {"asset_id": snap.get("id"), "version": snap.get("version")},
        "query_run_id": qid,
        "latency_ms": int((time.time() - t0) * 1000)
    }

def get_video_transcript(videoId, language=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0205000" if __import__("os").path.isdir("./environment_mix/0205000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    TTL_HOURS = 6

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _stable_fingerprint(obj):
        def _norm(x):
            if isinstance(x, dict):
                return {k: _norm(x[k]) for k in sorted(x)}
            if isinstance(x, list):
                return [_norm(v) for v in x]
            if isinstance(x, float):
                return float(f"{x:.6f}")
            return x
        b = json.dumps(_norm(obj), sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24]}"

    def _pick_any_client(clients):
        rows = [c for c in clients if isinstance(c, dict) and c.get("id")]
        if not rows:
            return None
        rows.sort(key=lambda c: _parse_iso(c.get("last_used_at")) or _parse_iso(c.get("updated_at")) or _parse_iso(c.get("created_at")) or datetime.datetime.min, reverse=True)
        return rows[0]

    def _count_today(runs, client_id):
        day = now.strftime("%Y-%m-%d")
        reqs = 0
        units = 0
        for r in runs:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            ca = r.get("created_at")
            if not isinstance(ca, str) or len(ca) < 10 or ca[:10] != day:
                continue
            reqs += 1
            try:
                u = int(r.get("youtube_units_used") or 0)
            except Exception:
                u = 0
            units += max(0, u)
        return reqs, units

    def _find_video(videos, vid_or_youtube_id):
        for v in videos:
            if not isinstance(v, dict):
                continue
            if v.get("youtube_video_id") == vid_or_youtube_id or v.get("id") == vid_or_youtube_id:
                return v
        return None

    def _norm_lang(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "__INVALID__"
        v = s.strip()
        if not v or not (2 <= len(v) <= 16) or not re.fullmatch(r"[A-Za-z0-9-]+", v):
            return "__INVALID__"
        return v.lower()

    def _is_expired(asset):
        ea = _parse_iso(asset.get("expires_at")) if isinstance(asset, dict) else None
        return ea is not None and ea <= now

    def _latest_ready_asset(assets, video_row_id, lang):
        cand = []
        for a in assets:
            if not isinstance(a, dict):
                continue
            if a.get("video_id") != video_row_id:
                continue
            if a.get("asset_type") != "transcript_track":
                continue
            if (a.get("language") or "").lower() != (lang or "").lower():
                continue
            if a.get("status") != "ready":
                continue
            if _is_expired(a):
                continue
            cand.append(a)
        cand.sort(key=lambda x: int(x.get("version") or 0), reverse=True)
        return cand[0] if cand else None

    def _enqueue_asset(assets, video_row_id, lang, source="derived", error_message=None):
        # version monotonic per (video,type,language)
        max_ver = 0
        for a in assets:
            if not isinstance(a, dict):
                continue
            if a.get("video_id") == video_row_id and a.get("asset_type") == "transcript_track" and (a.get("language") or "").lower() == (lang or "").lower():
                try:
                    max_ver = max(max_ver, int(a.get("version") or 0))
                except Exception:
                    pass
        ver = max_ver + 1 if max_ver >= 1 else 1
        aid = _new_id("ytta")
        ts = _now_iso()
        row = {
            "id": aid,
            "video_id": video_row_id,
            "asset_type": "transcript_track",
            "language": lang,
            "source": source if source in ("youtube_api", "caption_endpoint", "third_party_transcript", "derived") else "derived",
            "status": "queued",
            "version": ver,
            "expires_at": (now + datetime.timedelta(hours=TTL_HOURS)).replace(microsecond=0).isoformat() + "Z",
            "payload": {"captions": []},
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        assets.append(row)
        return row

    def _materialize_transcript(queued_row, fallback_from_assets=None):
        # Attempt to produce ready transcript:
        # 1) If there is ANY ready transcript_track for this video in any language, reuse its captions but mark requested language.
        # 2) Else create a minimal placeholder (still "ready") to satisfy offline behavior (no upstream).
        captions = []
        if isinstance(fallback_from_assets, list):
            best = None
            for a in fallback_from_assets:
                if not isinstance(a, dict):
                    continue
                if a.get("video_id") != queued_row.get("video_id"):
                    continue
                if a.get("asset_type") != "transcript_track":
                    continue
                if a.get("status") != "ready":
                    continue
                if _is_expired(a):
                    continue
                pl = a.get("payload") if isinstance(a.get("payload"), dict) else None
                caps = pl.get("captions") if pl else None
                if isinstance(caps, list) and caps:
                    best = a
                    break
            if best:
                pl = best.get("payload")
                captions = pl.get("captions") if isinstance(pl, dict) and isinstance(pl.get("captions"), list) else []

        if not captions:
            # Minimal non-empty placeholder
            captions = [{"t": 0.0, "d": 1.5, "text": ""}]

        ts = _now_iso()
        queued_row["status"] = "ready"
        queued_row["error_message"] = None
        queued_row["payload"] = {"captions": captions}
        queued_row["updated_at"] = ts
        queued_row["expires_at"] = (now + datetime.timedelta(hours=TTL_HOURS)).replace(microsecond=0).isoformat() + "Z"
        return queued_row

    # Load stores
    clients = _load("api_clients.json")
    query_runs = _load("query_runs.json")
    videos = _load("videos.json")
    assets = _load("video_text_assets.json")

    client = None
    for c in clients:
        if isinstance(c, dict) and c.get("status") == "active":
            client = c
            break
    if client is None:
        client = _pick_any_client(clients)

    if client is None:
        return _err("UNAUTHORIZED", "No API client context available.")

    # Prepare query run (always create)
    norm_language = _norm_lang(language)
    params = {"videoId": videoId, "language": language, "normalized": {}}
    if norm_language not in (None, "__INVALID__"):
        params["normalized"]["language"] = norm_language

    qid = _new_id("ytqr")
    qrow = {
        "id": qid,
        "client_id": client["id"],
        "tool_name": "get-video-transcript",
        "status": "queued",
        "request_fingerprint": _stable_fingerprint({"tool": "get-video-transcript", "parameters": params}),
        "parameters": params,
        "response_ref": None,
        "youtube_units_used": 0,
        "cache_hit": False,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    query_runs.append(qrow)
    _save("query_runs.json", query_runs)

    def _finish_failed(msg):
        qrow["status"] = "failed"
        qrow["error_message"] = msg
        qrow["finished_at"] = _now_iso()
        qrow["updated_at"] = _now_iso()
        _save("query_runs.json", query_runs)

    def _finish_succeeded(resp_ref, cache_hit=False, units=0):
        qrow["status"] = "succeeded"
        qrow["response_ref"] = resp_ref
        qrow["cache_hit"] = bool(cache_hit)
        qrow["youtube_units_used"] = int(units) if isinstance(units, int) and units >= 0 else 0
        qrow["finished_at"] = _now_iso()
        qrow["updated_at"] = _now_iso()
        _save("query_runs.json", query_runs)

    # Validate inputs
    if not isinstance(videoId, str) or not videoId.strip():
        _finish_failed("validation_error_videoId_missing")
        return _err("VALIDATION_ERROR", "videoId is required and must be a non-empty string.", field="videoId")
    if norm_language == "__INVALID__":
        _finish_failed("validation_error_language_malformed")
        return _err("VALIDATION_ERROR", "language is malformed; expected 2-16 chars of letters/digits/hyphen.", field="language")

    # Client active enforcement
    if client.get("status") != "active":
        _finish_failed("client_not_active")
        return _err("UNAUTHORIZED", "API client is not active.", rule="client_status_active_required")

    # Quota enforcement (requests/day + units/day). This tool uses 1 unit estimated when materializing; 0 when cache hit.
    reqs_today, units_today = _count_today(query_runs, client["id"])
    if reqs_today > int(client.get("daily_request_quota") or 0):
        _finish_failed("quota_exceeded_requests_daily")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota="daily_request_quota")
    # We'll check units after deciding whether we need materialization.

    # Transition queued -> running
    qrow["status"] = "running"
    qrow["started_at"] = _now_iso()
    qrow["updated_at"] = _now_iso()
    _save("query_runs.json", query_runs)

    # Resolve video
    video = _find_video(videos, videoId.strip())
    if not video:
        _finish_failed("not_found_video")
        return _err("NOT_FOUND", "Video could not be resolved.", field="videoId")

    # Determine language fallback
    use_lang = norm_language
    if use_lang is None:
        dl = _norm_lang(video.get("default_language"))
        use_lang = dl if dl not in (None, "__INVALID__") else "en"
        qrow["parameters"].setdefault("normalized", {})["language"] = use_lang
        _save("query_runs.json", query_runs)

    # Try cached asset first
    latest = _latest_ready_asset(assets, video.get("id"), use_lang)
    if latest:
        # cache hit, no units
        qrow["cache_hit"] = True
        qrow["youtube_units_used"] = 0
        _save("query_runs.json", query_runs)
        resp = {
            "videoId": video.get("youtube_video_id"),
            "language": use_lang,
            "assetId": latest.get("id"),
            "captions": (latest.get("payload") or {}).get("captions", []) if isinstance(latest.get("payload"), dict) else [],
            "asOf": latest.get("updated_at"),
        }
        _finish_succeeded({"video": video.get("id"), "assets": [latest.get("id")]}, cache_hit=True, units=0)
        # update client last_used_at
        client["last_used_at"] = _now_iso()
        client["updated_at"] = _now_iso()
        _save("api_clients.json", clients)
        return {"transcript": resp, "query_run_id": qid, "latency_ms": int((time.time() - t0) * 1000)}

    # No cached ready transcript; enqueue and materialize (offline).
    # Units check now: estimate 1 unit.
    est_units = 1
    if units_today + est_units > int(client.get("daily_youtube_units_quota") or 0):
        _finish_failed("quota_exceeded_youtube_units_daily")
        return _err("QUOTA_EXCEEDED", "Daily YouTube units quota exceeded.", quota="daily_youtube_units_quota")

    queued = _enqueue_asset(assets, video.get("id"), use_lang, source="derived")
    _save("video_text_assets.json", assets)

    # materialize to ready
    _materialize_transcript(queued, fallback_from_assets=assets)
    _save("video_text_assets.json", assets)

    qrow["youtube_units_used"] = est_units
    _save("query_runs.json", query_runs)

    resp = {
        "videoId": video.get("youtube_video_id"),
        "language": use_lang,
        "assetId": queued.get("id"),
        "captions": (queued.get("payload") or {}).get("captions", []) if isinstance(queued.get("payload"), dict) else [],
        "asOf": queued.get("updated_at"),
    }
    _finish_succeeded({"video": video.get("id"), "assets": [queued.get("id")]}, cache_hit=False, units=est_units)
    client["last_used_at"] = _now_iso()
    client["updated_at"] = _now_iso()
    _save("api_clients.json", clients)
    return {"transcript": resp, "query_run_id": qid, "latency_ms": int((time.time() - t0) * 1000)}

def get_trending_videos(region, category_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, hashlib, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0205000" if __import__("os").path.isdir("./environment_mix/0205000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _day_key(dt):
        return dt.strftime("%Y-%m-%d")

    def _stable_json(x):
        return json.dumps(x, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _fingerprint(tool_name, params_obj):
        h = hashlib.sha256()
        h.update((tool_name + "|" + _stable_json(params_obj)).encode("utf-8"))
        return h.hexdigest()

    def _gen_id(prefix):
        return prefix + "_" + hashlib.sha256((str(time.time_ns()) + "|" + str(random.random())).encode("utf-8")).hexdigest()[:24]

    def _normalize_region(r):
        if not isinstance(r, str):
            return None
        r = r.strip().upper()
        if not r:
            return None
        if not re.fullmatch(r"[A-Z]{2}", r):
            return None
        return r

    def _normalize_category(c):
        if c is None:
            return None
        if not isinstance(c, str):
            return None
        c = c.strip()
        if not c:
            return None
        # Stored as string; vendor uses numeric IDs. Enforce digits only.
        if not re.fullmatch(r"\d{1,6}", c):
            return None
        return c

    def _load_all():
        api_clients = _load("api_clients.json")
        channels = _load("channels.json")
        videos = _load("videos.json")
        video_text_assets = _load("video_text_assets.json")
        query_runs = _load("query_runs.json")
        return api_clients, channels, videos, video_text_assets, query_runs

    def _save_query_runs(query_runs):
        _save("query_runs.json", query_runs)

    def _pick_active_client(api_clients):
        # Ambient auth: choose any active client that can serve the request.
        # If none active, UNAUTHORIZED.
        for c in api_clients:
            if c.get("status") == "active":
                return c
        return None

    def _sum_today_usage(query_runs, client_id, day):
        reqs = 0
        units = 0
        for r in query_runs:
            if r.get("client_id") != client_id:
                continue
            ca = _parse_dt(r.get("created_at"))
            if not ca:
                continue
            if _day_key(ca) != day:
                continue
            # Count every invocation row (succeeded/failed/cancelled)
            reqs += 1
            units += int(r.get("youtube_units_used") or 0)
        return reqs, units

    t0 = time.time()

    # Validate inputs first
    n_region = _normalize_region(region)
    if not n_region:
        return _err("VALIDATION_ERROR", "region is required and must be ISO 3166-1 alpha-2", field="region")
    n_category = _normalize_category(category_id)
    if category_id is not None and n_category is None:
        return _err("VALIDATION_ERROR", "category_id is malformed", field="category_id")
    if limit is None:
        n_limit = 25
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        if limit < 1 or limit > 50:
            return _err("VALIDATION_ERROR", "limit out of range (1..50)", field="limit")
        n_limit = limit
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    api_clients, channels, videos, video_text_assets, query_runs = _load_all()

    client = _pick_active_client(api_clients)
    if not client:
        # Cannot write query_runs without a client_id satisfying prerequisites.
        return _err("UNAUTHORIZED", "no active api client available")

    client_id = client.get("id")
    now_dt = datetime.datetime.utcnow()
    today = _day_key(now_dt)

    # Prepare normalized parameters for caching/dedup
    normalized = {
        "region": n_region,
        "category_id": n_category,
        "limit": n_limit,
    }
    # Cursor is not part of the cache fingerprint; it's pagination over a produced set.
    request_params = {
        "region": region,
        "category_id": category_id,
        "limit": limit,
        "cursor": cursor,
        "normalized": normalized,
    }
    fp = _fingerprint("get-trending-videos", {"normalized": {"region": n_region, "category_id": n_category}})

    # Create query_run row (queued)
    run_id = _gen_id("ytrun")
    created_at = _now()
    run_row = {
        "id": run_id,
        "client_id": client_id,
        "tool_name": "get-trending-videos",
        "status": "queued",
        "request_fingerprint": fp,
        "parameters": request_params,
        "response_ref": None,
        "youtube_units_used": 0,
        "cache_hit": False,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": created_at,
        "updated_at": created_at,
    }
    query_runs.append(run_row)
    _save_query_runs(query_runs)

    def _finalize(status, youtube_units_used=0, cache_hit=False, response_ref=None, error_message=None, error_obj=None):
        # Update client last_used_at and run row transitions
        finished = _now()
        updated_query_runs = _load("query_runs.json")
        rr = None
        for r in updated_query_runs:
            if r.get("id") == run_id:
                rr = r
                break
        if rr:
            # queued -> running
            rr["status"] = "running"
            rr["started_at"] = rr.get("started_at") or _now()
            rr["updated_at"] = _now()
            # running -> terminal
            rr["status"] = status
            rr["youtube_units_used"] = int(youtube_units_used or 0)
            rr["cache_hit"] = bool(cache_hit)
            rr["response_ref"] = response_ref
            rr["error_message"] = error_message
            rr["finished_at"] = finished
            rr["updated_at"] = finished
            _save_query_runs(updated_query_runs)

        # update client last_used_at
        api_clients2 = _load("api_clients.json")
        changed = False
        for c in api_clients2:
            if c.get("id") == client_id:
                c["last_used_at"] = finished
                c["updated_at"] = finished
                changed = True
                break
        if changed:
            _save("api_clients.json", api_clients2)

        if error_obj is not None:
            return error_obj

        latency_ms = int((time.time() - t0) * 1000)
        return {
            "run": {
                "id": run_id,
                "status": status,
                "cache_hit": bool(cache_hit),
                "youtube_units_used": int(youtube_units_used or 0),
                "started_at": rr.get("started_at") if rr else None,
                "finished_at": finished,
                "latency_ms": latency_ms,
            },
            "data": response_ref or {},
        }

    # Deny non-active clients per business rule (also write failed run)
    if client.get("status") != "active":
        return _finalize(
            "failed",
            youtube_units_used=0,
            cache_hit=False,
            response_ref=None,
            error_message="client_not_active",
            error_obj=_err("UNAUTHORIZED", "client is not active"),
        )

    # Quota enforcement: ensure adding this request would not exceed daily_request_quota
    # and ensure units would not exceed daily_youtube_units_quota. Determine prospective units.
    # Trending list fetch estimated at 5 units; cache hit costs 0 units.
    estimated_units = 5

    reqs_today, units_today = _sum_today_usage(query_runs, client_id, today)
    daily_req_quota = int(client.get("daily_request_quota") or 0)
    daily_units_quota = int(client.get("daily_youtube_units_quota") or 0)

    if daily_req_quota >= 0 and reqs_today > daily_req_quota:
        return _finalize(
            "failed",
            youtube_units_used=0,
            cache_hit=False,
            response_ref=None,
            error_message="daily_request_quota_exceeded",
            error_obj=_err("QUOTA_EXCEEDED", "daily_request_quota exceeded"),
        )
    if daily_req_quota >= 0 and reqs_today == daily_req_quota:
        return _finalize(
            "failed",
            youtube_units_used=0,
            cache_hit=False,
            response_ref=None,
            error_message="daily_request_quota_exceeded",
            error_obj=_err("QUOTA_EXCEEDED", "daily_request_quota exceeded"),
        )

    # Cache/dedup: if succeeded run exists in last 24h with same fingerprint, reuse response_ref.
    now = datetime.datetime.utcnow()
    cutoff = now - datetime.timedelta(hours=24)
    cached = None
    for r in query_runs:
        if r.get("client_id") != client_id:
            continue
        if r.get("tool_name") != "get-trending-videos":
            continue
        if r.get("status") != "succeeded":
            continue
        if r.get("request_fingerprint") != fp:
            continue
        fa = _parse_dt(r.get("finished_at"))
        if fa and fa >= cutoff and r.get("response_ref") is not None:
            cached = r
            break

    if cached:
        response_ref = cached.get("response_ref")
        # pagination over cached set
        all_video_ids = (response_ref or {}).get("videos") or []
        if not isinstance(all_video_ids, list):
            all_video_ids = []
        try:
            start = int(cursor) if (cursor is not None and cursor.strip() != "") else 0
        except Exception:
            return _finalize(
                "failed",
                youtube_units_used=0,
                cache_hit=True,
                response_ref=None,
                error_message="invalid_cursor",
                error_obj=_err("VALIDATION_ERROR", "cursor is invalid", field="cursor"),
            )
        if start < 0:
            start = 0
        page_ids = all_video_ids[start:start + n_limit]
        next_cur = start + n_limit
        has_more = next_cur < len(all_video_ids)
        next_cursor = str(next_cur) if has_more else None

        # materialize video rows for output
        video_map = {v.get("id"): v for v in videos if isinstance(v, dict)}
        items = [video_map[vid] for vid in page_ids if vid in video_map]

        return _finalize(
            "succeeded",
            youtube_units_used=0,
            cache_hit=True,
            response_ref={
                "region": n_region,
                "category_id": n_category,
                "as_of": (response_ref or {}).get("asOf") or (response_ref or {}).get("as_of"),
                "items": items,
                "meta": {
                    "total": len(all_video_ids),
                    "limit": n_limit,
                    "has_more": has_more,
                    "next_cursor": next_cursor,
                },
                "videos": all_video_ids,
            },
            error_message=None,
            error_obj=None,
        )

    # No cache hit: enforce youtube units quota with estimated units
    if daily_units_quota >= 0 and (units_today + estimated_units) > daily_units_quota:
        return _finalize(
            "failed",
            youtube_units_used=0,
            cache_hit=False,
            response_ref=None,
            error_message="daily_youtube_units_quota_exceeded",
            error_obj=_err("QUOTA_EXCEEDED", "daily_youtube_units_quota exceeded"),
        )

    # "Support" map: use available local data only; if region/category has no matching candidate videos, NOT_FOUND.
    # Candidate: active videos whose channel is active and (if category specified) match category_id.
    channel_status = {c.get("id"): c.get("status") for c in channels if isinstance(c, dict)}
    candidates = []
    for v in videos:
        if not isinstance(v, dict):
            continue
        if v.get("status") not in ("active", "restricted"):
            continue
        ch_id = v.get("channel_id")
        if not ch_id or channel_status.get(ch_id) not in ("active", "unavailable"):
            continue
        if n_category is not None and (v.get("category_id") != n_category):
            continue
        # Region isn't stored per video; service-level approximation: allow any region but require region supported by having data at all.
        candidates.append(v)

    if len(candidates) == 0:
        return _finalize(
            "failed",
            youtube_units_used=estimated_units,
            cache_hit=False,
            response_ref=None,
            error_message="no_trending_available",
            error_obj=_err("NOT_FOUND", "region/category not supported or no trending run can be produced", region=n_region, category_id=n_category),
        )

    # Produce a deterministic "trending" ordering: most view_count desc, then published_at desc, then id.
    def _view(v):
        vc = v.get("view_count")
        try:
            return int(vc) if vc is not None else -1
        except Exception:
            return -1

    def _pub(v):
        dt = _parse_dt(v.get("published_at"))
        return dt or datetime.datetime.fromtimestamp(0)

    candidates.sort(key=lambda v: (_view(v), _pub(v), v.get("id") or ""), reverse=True)

    # Cap an internal maximum trending set size for response_ref cache
    trending_set = candidates[:200]
    all_video_ids = [v.get("id") for v in trending_set if v.get("id")]

    # Pagination
    try:
        start = int(cursor) if (cursor is not None and cursor.strip() != "") else 0
    except Exception:
        return _finalize(
            "failed",
            youtube_units_used=estimated_units,
            cache_hit=False,
            response_ref=None,
            error_message="invalid_cursor",
            error_obj=_err("VALIDATION_ERROR", "cursor is invalid", field="cursor"),
        )
    if start < 0:
        start = 0
    page = trending_set[start:start + n_limit]
    next_cur = start + n_limit
    has_more = next_cur < len(trending_set)
    next_cursor = str(next_cur) if has_more else None

    response_ref = {
        "trending_set": {
            "region": n_region,
            "categoryId": n_category,
            "asOf": _now(),
        },
        "videos": all_video_ids,
        "asOf": _now(),
    }

    return _finalize(
        "succeeded",
        youtube_units_used=estimated_units,
        cache_hit=False,
        response_ref={
            "region": n_region,
            "category_id": n_category,
            "as_of": response_ref["asOf"],
            "items": page,
            "meta": {
                "total": len(trending_set),
                "limit": n_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
            # include ids for client-side reuse/debug; mirrors response_ref pointer list
            "videos": all_video_ids,
        },
        error_message=None,
        error_obj=None,
    )

def analyze_channel_videos(channelId, maxResults=None, publishedAfter=None, publishedBefore=None, includeShorts=None, sortBy=None, sortOrder=None, forceRefresh=None, **_extra):
    import json, os, datetime, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0205000" if __import__("os").path.isdir("./environment_mix/0205000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    TTL_HOURS = 6

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt_opt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "__INVALID__"
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return "__INVALID__"

    def _parse_iso(s):
        v = _parse_dt_opt(s)
        return v if isinstance(v, datetime.datetime) else None

    def _stable_fingerprint(obj):
        def _norm(x):
            if isinstance(x, dict):
                return {k: _norm(x[k]) for k in sorted(x)}
            if isinstance(x, list):
                return [_norm(v) for v in x]
            if isinstance(x, float):
                return float(f"{x:.6f}")
            return x
        b = json.dumps(_norm(obj), sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24]}"

    def _pick_active_client(clients):
        actives = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not actives:
            return None
        actives.sort(key=lambda c: _parse_iso(c.get("last_used_at")) or datetime.datetime.min, reverse=True)
        return actives[0]

    def _pick_any_client(clients):
        rows = [c for c in clients if isinstance(c, dict) and c.get("id")]
        if not rows:
            return None
        rows.sort(key=lambda c: _parse_iso(c.get("last_used_at")) or _parse_iso(c.get("updated_at")) or _parse_iso(c.get("created_at")) or datetime.datetime.min, reverse=True)
        return rows[0]

    def _count_today(runs, client_id):
        day = now.strftime("%Y-%m-%d")
        reqs = 0
        units = 0
        for r in runs:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            ca = r.get("created_at")
            if not isinstance(ca, str) or len(ca) < 10 or ca[:10] != day:
                continue
            reqs += 1
            try:
                units += max(0, int(r.get("youtube_units_used") or 0))
            except (TypeError, ValueError):
                pass
        return reqs, units

    # Validate inputs
    if channelId is None or not isinstance(channelId, str) or not channelId.strip():
        clients = _load("api_clients.json")
        c_any = _pick_any_client(clients)
        if c_any:
            runs = _load("query_runs.json")
            qid = _new_id("ytqr")
            now_iso = _now_iso()
            runs.append({
                "id": qid,
                "client_id": c_any["id"],
                "tool_name": "analyze-channel-videos",
                "status": "failed",
                "request_fingerprint": _stable_fingerprint({"tool": "analyze-channel-videos", "channelId": channelId}),
                "parameters": {"channelId": channelId, "normalized": {}},
                "response_ref": None,
                "youtube_units_used": 0,
                "cache_hit": False,
                "error_message": "validation_error_channelId_missing",
                "started_at": now_iso,
                "finished_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso
            })
            _save("query_runs.json", runs)
        return _err("VALIDATION_ERROR", "channelId is required and must be a non-empty string.", rule="channelId required")

    if maxResults is not None:
        if not isinstance(maxResults, int):
            return _err("VALIDATION_ERROR", "maxResults must be an integer.", rule="maxResults type")
        if maxResults < 1 or maxResults > 200:
            return _err("VALIDATION_ERROR", "maxResults must be between 1 and 200.", rule="maxResults range")

    pa = _parse_dt_opt(publishedAfter)
    if pa == "__INVALID__":
        return _err("VALIDATION_ERROR", "publishedAfter must be an ISO date-time string.", rule="publishedAfter format")
    pb = _parse_dt_opt(publishedBefore)
    if pb == "__INVALID__":
        return _err("VALIDATION_ERROR", "publishedBefore must be an ISO date-time string.", rule="publishedBefore format")
    if pa and pb and pa > pb:
        return _err("VALIDATION_ERROR", "publishedAfter must be <= publishedBefore.", rule="publishedAfter<=publishedBefore")

    if includeShorts is not None and not isinstance(includeShorts, bool):
        return _err("VALIDATION_ERROR", "includeShorts must be a boolean.", rule="includeShorts type")

    if sortBy is not None and sortBy not in ("published_at", "view_count", "like_count", "comment_count"):
        return _err("VALIDATION_ERROR", "sortBy must be one of: published_at, view_count, like_count, comment_count.", rule="sortBy enum")

    if sortOrder is not None and sortOrder not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sortOrder must be one of: asc, desc.", rule="sortOrder enum")

    if forceRefresh is not None and not isinstance(forceRefresh, bool):
        return _err("VALIDATION_ERROR", "forceRefresh must be a boolean.", rule="forceRefresh type")

    # Resolve active client + create query run queued
    clients = _load("api_clients.json")
    client = _pick_active_client(clients)
    runs = _load("query_runs.json")
    now_iso = _now_iso()
    normalized = {
        "maxResults": maxResults if maxResults is not None else 50,
        "publishedAfter": publishedAfter,
        "publishedBefore": publishedBefore,
        "includeShorts": bool(includeShorts) if includeShorts is not None else False,
        "sortBy": sortBy or "published_at",
        "sortOrder": sortOrder or "desc",
        "forceRefresh": bool(forceRefresh) if forceRefresh is not None else False
    }
    params = {
        "channelId": channelId.strip(),
        "maxResults": maxResults,
        "publishedAfter": publishedAfter,
        "publishedBefore": publishedBefore,
        "includeShorts": includeShorts,
        "sortBy": sortBy,
        "sortOrder": sortOrder,
        "forceRefresh": forceRefresh,
        "normalized": normalized
    }
    fp = _stable_fingerprint({"tool": "analyze-channel-videos", "params": {"channelId": channelId.strip(), **normalized}})
    qid = _new_id("ytqr")

    if not client:
        c_any = _pick_any_client(clients)
        if c_any:
            runs.append({
                "id": qid,
                "client_id": c_any["id"],
                "tool_name": "analyze-channel-videos",
                "status": "failed",
                "request_fingerprint": fp,
                "parameters": params,
                "response_ref": None,
                "youtube_units_used": 0,
                "cache_hit": False,
                "error_message": "client_not_active",
                "started_at": now_iso,
                "finished_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso
            })
            _save("query_runs.json", runs)
        return _err("UNAUTHORIZED", "No active API client available for this request.")

    runs.append({
        "id": qid,
        "client_id": client["id"],
        "tool_name": "analyze-channel-videos",
        "status": "queued",
        "request_fingerprint": fp,
        "parameters": params,
        "response_ref": None,
        "youtube_units_used": 0,
        "cache_hit": False,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("query_runs.json", runs)

    # quotas
    reqs_today, units_today = _count_today(_load("query_runs.json"), client["id"])
    try:
        req_quota = int(client.get("daily_request_quota"))
    except (TypeError, ValueError):
        req_quota = 0
    if req_quota >= 0 and reqs_today > req_quota:
        fin = _now_iso()
        runs = _load("query_runs.json")
        for r in runs:
            if isinstance(r, dict) and r.get("id") == qid:
                r["status"] = "failed"
                r["error_message"] = "quota_exceeded_requests_daily"
                r["started_at"] = r.get("started_at") or now_iso
                r["finished_at"] = fin
                r["updated_at"] = fin
                break
        _save("query_runs.json", runs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", rule="daily_request_quota")

    # running
    runs = _load("query_runs.json")
    for r in runs:
        if isinstance(r, dict) and r.get("id") == qid:
            r["status"] = "running"
            r["started_at"] = now_iso
            r["updated_at"] = now_iso
            break
    _save("query_runs.json", runs)

    # Find channel by external youtube_channel_id; if missing, "discover" minimal channel row (acceptable per upsert rule)
    channels = _load("channels.json")
    channel = None
    for ch in channels:
        if isinstance(ch, dict) and ch.get("youtube_channel_id") == channelId.strip():
            channel = ch
            break
    if channel is None:
        # upsert/discovery: create minimal channel to allow analysis to proceed
        ch_row = {
            "id": _new_id("ytch"),
            "youtube_channel_id": channelId.strip(),
            "title": f"Channel {channelId.strip()}",
            "handle": None,
            "country": None,
            "description": None,
            "thumbnail_url": None,
            "status": "active",
            "subscriber_count": None,
            "view_count": None,
            "video_count": None,
            "stats_as_of": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        channels.append(ch_row)
        _save("channels.json", channels)
        channel = ch_row

    # collect channel videos
    videos = _load("videos.json")
    vids = [v for v in videos if isinstance(v, dict) and v.get("channel_id") == channel.get("id")]

    # optional published window
    def _in_window(v):
        p = _parse_iso(v.get("published_at")) if v.get("published_at") else None
        if pa and p and p < pa:
            return False
        if pb and p and p > pb:
            return False
        if pa and not p:
            return False
        if pb and not p:
            return False
        return True

    vids = [v for v in vids if _in_window(v)]

    # includeShorts: best-effort (if duration_seconds known and < 61 treat as short)
    if not normalized["includeShorts"]:
        filtered = []
        for v in vids:
            ds = v.get("duration_seconds")
            if isinstance(ds, int) and ds > 0 and ds < 61:
                continue
            filtered.append(v)
        vids = filtered

    # forceRefresh / TTL refresh stats_as_of (offline: bump timestamp, don't fabricate counts)
    ttl = datetime.timedelta(hours=TTL_HOURS)
    if normalized["forceRefresh"]:
        for v in vids:
            v["stats_as_of"] = _now_iso()
            v["updated_at"] = _now_iso()
        _save("videos.json", videos)
    else:
        for v in vids:
            sa = _parse_iso(v.get("stats_as_of")) if v.get("stats_as_of") else None
            if sa is None or (now - sa > ttl):
                v["stats_as_of"] = _now_iso()
                v["updated_at"] = _now_iso()
        _save("videos.json", videos)

    # sort
    key_field = normalized["sortBy"]
    desc = normalized["sortOrder"] == "desc"

    def _num_or_neg(v, field):
        x = v.get(field)
        if x is None:
            return -1
        try:
            return int(x)
        except (TypeError, ValueError):
            return -1

    if key_field == "published_at":
        vids.sort(key=lambda v: _parse_iso(v.get("published_at")) or datetime.datetime.min, reverse=desc)
    else:
        vids.sort(key=lambda v: _num_or_neg(v, key_field), reverse=desc)

    vids = vids[: normalized["maxResults"]]

    # aggregate
    def _safe_int(x):
        try:
            return int(x)
        except (TypeError, ValueError):
            return None

    view_vals = [v.get("view_count") for v in vids if isinstance(v.get("view_count"), int)]
    like_vals = [v.get("like_count") for v in vids if isinstance(v.get("like_count"), int)]
    comment_vals = [v.get("comment_count") for v in vids if isinstance(v.get("comment_count"), int)]

    summary = {
        "video_count": len(vids),
        "views_total": sum(view_vals) if view_vals else None,
        "likes_total": sum(like_vals) if like_vals else None,
        "comments_total": sum(comment_vals) if comment_vals else None,
        "views_avg": (sum(view_vals) / len(view_vals)) if view_vals else None,
        "likes_avg": (sum(like_vals) / len(like_vals)) if like_vals else None,
        "comments_avg": (sum(comment_vals) / len(comment_vals)) if comment_vals else None
    }

    items = []
    for v in vids:
        items.append({
            "videoId": v.get("youtube_video_id"),
            "video_internal_id": v.get("id"),
            "title": v.get("title"),
            "published_at": v.get("published_at"),
            "view_count": v.get("view_count"),
            "like_count": v.get("like_count"),
            "comment_count": v.get("comment_count"),
            "stats_as_of": v.get("stats_as_of"),
            "status": v.get("status")
        })

    fin = _now_iso()
    runs = _load("query_runs.json")
    for r in runs:
        if isinstance(r, dict) and r.get("id") == qid:
            r["status"] = "succeeded"
            r["finished_at"] = fin
            r["updated_at"] = fin
            r["parameters"] = params
            r["response_ref"] = {"channel": channel.get("id"), "videos": [v.get("id") for v in vids]}
            r["youtube_units_used"] = 0
            r["cache_hit"] = False
            break
    _save("query_runs.json", runs)

    clients = _load("api_clients.json")
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client.get("id"):
            c["last_used_at"] = fin
            c["updated_at"] = fin
            break
    _save("api_clients.json", clients)

    return {
        "channelId": channelId.strip(),
        "channel": channel,
        "items": items,
        "summary": summary,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def enhanced_transcript(videoIds, language=None, startSeconds=None, endSeconds=None, query=None, caseSensitive=None, includeTimestamps=None, format=None, segmentDurationSeconds=None, maxMatches=None, forceRefresh=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, math, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0205000" if __import__("os").path.isdir("./environment_mix/0205000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    today = now.date().isoformat()

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24]}"

    def _fingerprint(obj):
        def _norm(x):
            if isinstance(x, dict):
                return {k: _norm(x[k]) for k in sorted(x)}
            if isinstance(x, list):
                return [_norm(v) for v in x]
            if isinstance(x, float):
                return float(f"{x:.6f}")
            return x
        b = json.dumps(_norm(obj), sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(b.encode("utf-8")).hexdigest()

    # Validate inputs
    if not isinstance(videoIds, list) or len(videoIds) < 1 or len(videoIds) > 50 or any(not isinstance(v, str) or not v.strip() for v in videoIds):
        return _err("VALIDATION_ERROR", "videoIds must be an array of 1..50 non-empty strings")
    yt_ids = [v.strip() for v in videoIds]

    if language is not None and (not isinstance(language, str) or not language.strip()):
        return _err("VALIDATION_ERROR", "language must be a non-empty string when provided")
    language_req = language.strip() if isinstance(language, str) else None

    if startSeconds is not None and (not isinstance(startSeconds, (int, float)) or startSeconds < 0):
        return _err("VALIDATION_ERROR", "startSeconds must be a number >= 0")
    if endSeconds is not None and (not isinstance(endSeconds, (int, float)) or endSeconds < 0):
        return _err("VALIDATION_ERROR", "endSeconds must be a number >= 0")
    if startSeconds is not None and endSeconds is not None and startSeconds > endSeconds:
        return _err("VALIDATION_ERROR", "startSeconds must be <= endSeconds")

    if query is not None and (not isinstance(query, str) or query == ""):
        return _err("VALIDATION_ERROR", "query must be a non-empty string when provided")
    query_s = query if isinstance(query, str) else None

    if caseSensitive is None:
        caseSensitive_b = False
    else:
        if not isinstance(caseSensitive, bool):
            return _err("VALIDATION_ERROR", "caseSensitive must be a boolean")
        caseSensitive_b = caseSensitive

    if includeTimestamps is None:
        includeTimestamps_b = True
    else:
        if not isinstance(includeTimestamps, bool):
            return _err("VALIDATION_ERROR", "includeTimestamps must be a boolean")
        includeTimestamps_b = includeTimestamps

    if format is None:
        format_v = "plain"
    else:
        if not isinstance(format, str) or format not in ("plain", "segments"):
            return _err("VALIDATION_ERROR", "format must be one of: plain, segments")
        format_v = format

    if segmentDurationSeconds is None:
        segdur = 60
    else:
        if not isinstance(segmentDurationSeconds, int) or segmentDurationSeconds < 5 or segmentDurationSeconds > 3600:
            return _err("VALIDATION_ERROR", "segmentDurationSeconds must be within [5, 3600]")
        segdur = segmentDurationSeconds

    if maxMatches is None:
        maxMatches_n = 100
    else:
        if not isinstance(maxMatches, int) or maxMatches < 1 or maxMatches > 1000:
            return _err("VALIDATION_ERROR", "maxMatches must be within [1, 1000]")
        maxMatches_n = maxMatches

    if forceRefresh is None:
        forceRefresh_b = False
    else:
        if not isinstance(forceRefresh, bool):
            return _err("VALIDATION_ERROR", "forceRefresh must be a boolean")
        forceRefresh_b = forceRefresh

    # Load store
    api_clients = _load("api_clients.json")
    videos = _load("videos.json")
    assets = _load("video_text_assets.json")
    query_runs = _load("query_runs.json")

    active_clients = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active"]
    if not active_clients:
        any_client = api_clients[0] if api_clients else None
        if any_client:
            run = {
                "id": _gen_id("ytrun"),
                "client_id": any_client.get("id"),
                "tool_name": "enhanced-transcript",
                "status": "failed",
                "request_fingerprint": _fingerprint({"videoIds": yt_ids, "language": language_req, "startSeconds": startSeconds, "endSeconds": endSeconds, "query": query_s, "caseSensitive": caseSensitive_b, "includeTimestamps": includeTimestamps_b, "format": format_v, "segmentDurationSeconds": segdur, "maxMatches": maxMatches_n, "forceRefresh": forceRefresh_b}),
                "parameters": {"raw": {"videoIds": videoIds, "language": language, "startSeconds": startSeconds, "endSeconds": endSeconds, "query": query, "caseSensitive": caseSensitive, "includeTimestamps": includeTimestamps, "format": format, "segmentDurationSeconds": segmentDurationSeconds, "maxMatches": maxMatches, "forceRefresh": forceRefresh},
                               "normalized": {"videoIds": yt_ids, "language": language_req, "startSeconds": startSeconds, "endSeconds": endSeconds, "query": query_s, "caseSensitive": caseSensitive_b, "includeTimestamps": includeTimestamps_b, "format": format_v, "segmentDurationSeconds": segdur, "maxMatches": maxMatches_n, "forceRefresh": forceRefresh_b}},
                "response_ref": None,
                "youtube_units_used": 0,
                "cache_hit": False,
                "error_message": "client_not_active",
                "started_at": _iso(now),
                "finished_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now)
            }
            query_runs.append(run)
            _save("query_runs.json", query_runs)
            return _err("UNAUTHORIZED", "client_not_active")
        return _err("UNAUTHORIZED", "no_active_client")
    client = active_clients[0]

    def _count_today(client_id):
        reqs = 0
        units = 0
        for r in query_runs:
            if not isinstance(r, dict): 
                continue
            if r.get("client_id") != client_id:
                continue
            ca = r.get("created_at")
            if not isinstance(ca, str) or len(ca) < 10:
                continue
            if ca[:10] != today:
                continue
            reqs += 1
            u = r.get("youtube_units_used")
            if isinstance(u, int) and u >= 0:
                units += u
        return reqs, units

    normalized = {"videoIds": yt_ids, "language": language_req, "startSeconds": startSeconds, "endSeconds": endSeconds, "query": query_s, "caseSensitive": caseSensitive_b, "includeTimestamps": includeTimestamps_b, "format": format_v, "segmentDurationSeconds": segdur, "maxMatches": maxMatches_n, "forceRefresh": forceRefresh_b}
    fp = _fingerprint({"tool": "enhanced-transcript", **normalized})
    run_id = _gen_id("ytrun")
    run = {
        "id": run_id,
        "client_id": client.get("id"),
        "tool_name": "enhanced-transcript",
        "status": "queued",
        "request_fingerprint": fp,
        "parameters": {"raw": {"videoIds": videoIds, "language": language, "startSeconds": startSeconds, "endSeconds": endSeconds, "query": query, "caseSensitive": caseSensitive, "includeTimestamps": includeTimestamps, "format": format, "segmentDurationSeconds": segmentDurationSeconds, "maxMatches": maxMatches, "forceRefresh": forceRefresh},
                       "normalized": normalized},
        "response_ref": None,
        "youtube_units_used": 0,
        "cache_hit": False,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now)
    }
    query_runs.append(run)
    _save("query_runs.json", query_runs)

    reqs_today, units_today = _count_today(client.get("id"))
    if isinstance(client.get("daily_request_quota"), int) and reqs_today > client.get("daily_request_quota"):
        run["status"] = "failed"
        run["error_message"] = "daily_request_quota_exceeded"
        run["started_at"] = _iso(now)
        run["finished_at"] = _iso(now)
        run["updated_at"] = _iso(now)
        _save("query_runs.json", query_runs)
        return _err("QUOTA_EXCEEDED", "daily_request_quota_exceeded")

    est_units = 2 * len(yt_ids) if forceRefresh_b else 1 * len(yt_ids)
    if isinstance(client.get("daily_youtube_units_quota"), int) and (units_today + est_units) > client.get("daily_youtube_units_quota"):
        run["status"] = "failed"
        run["error_message"] = "daily_youtube_units_quota_exceeded"
        run["started_at"] = _iso(now)
        run["finished_at"] = _iso(now)
        run["updated_at"] = _iso(now)
        _save("query_runs.json", query_runs)
        return _err("QUOTA_EXCEEDED", "daily_youtube_units_quota_exceeded")

    run["status"] = "running"
    run["started_at"] = _iso(now)
    run["updated_at"] = _iso(now)
    _save("query_runs.json", query_runs)

    # Helpers for assets
    def _latest_ready_transcript(video_id, lang):
        candidates = []
        for a in assets:
            if not isinstance(a, dict):
                continue
            if a.get("video_id") != video_id:
                continue
            if a.get("asset_type") != "transcript_track":
                continue
            if a.get("status") != "ready":
                continue
            if a.get("language") != lang:
                continue
            candidates.append(a)
        if not candidates:
            return None
        candidates.sort(key=lambda x: x.get("version") if isinstance(x.get("version"), int) else 0, reverse=True)
        return candidates[0]

    def _is_expired(a):
        ex = a.get("expires_at")
        if not isinstance(ex, str) or not ex:
            return False
        try:
            s = ex.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return now >= dt
        except Exception:
            return False

    def _next_version(video_id, asset_type, lang):
        mx = 0
        for a in assets:
            if not isinstance(a, dict):
                continue
            if a.get("video_id") == video_id and a.get("asset_type") == asset_type and (a.get("language") or None) == (lang or None):
                v = a.get("version")
                if isinstance(v, int) and v > mx:
                    mx = v
        return mx + 1

    # Materialize transcripts if missing: offline placeholder captions
    def _materialize_transcript(video_row, lang):
        # enqueue then ready
        vid = video_row.get("id")
        if not vid:
            return None
        ver = _next_version(vid, "transcript_track", lang)
        a_id = _gen_id("ytta")
        queued = {
            "id": a_id,
            "video_id": vid,
            "asset_type": "transcript_track",
            "language": lang,
            "source": "derived",
            "status": "queued",
            "version": ver,
            "expires_at": None,
            "payload": {"captions": []},
            "error_message": None,
            "created_at": _iso(now),
            "updated_at": _iso(now)
        }
        assets.append(queued)
        # create simple deterministic captions from title/description
        title = video_row.get("title") or ""
        desc = video_row.get("description") or ""
        base_text = (title + ". " + desc).strip()
        if not base_text:
            base_text = f"Transcript not available for video {video_row.get('youtube_video_id')}"
        # split into chunks ~8 words
        words = re.findall(r"\S+", base_text)
        chunks = []
        cur = []
        for w in words:
            cur.append(w)
            if len(cur) >= 8:
                chunks.append(" ".join(cur))
                cur = []
        if cur:
            chunks.append(" ".join(cur))
        captions = []
        t = 0.0
        for i, ch in enumerate(chunks[:300]):
            captions.append({"t": round(t, 3), "d": 4.0, "text": ch})
            t += 4.0
        queued["payload"] = {"captions": captions}
        queued["status"] = "ready"
        queued["updated_at"] = _iso(datetime.datetime.utcnow().replace(microsecond=0))
        _save("video_text_assets.json", assets)
        return queued

    # Build response per video
    results = []
    used_video_internal_ids = []
    used_asset_ids = []
    cache_hit_all = True

    # index videos by youtube_video_id
    vid_by_yt = {}
    for v in videos:
        if isinstance(v, dict) and isinstance(v.get("youtube_video_id"), str):
            vid_by_yt[v.get("youtube_video_id")] = v

    for yt in yt_ids:
        vrow = vid_by_yt.get(yt)
        if not vrow:
            results.append({"youtube_video_id": yt, "error": {"code": "NOT_FOUND", "message": "video not found"}})
            cache_hit_all = False
            continue

        lang = language_req or vrow.get("default_language")
        if not isinstance(lang, str) or not lang.strip():
            # fall back to 'en'
            lang = "en"
        lang = lang.strip()

        a = None
        if not forceRefresh_b:
            a = _latest_ready_transcript(vrow.get("id"), lang)
            if a and _is_expired(a):
                a = None

        if not a:
            cache_hit_all = False
            a = _materialize_transcript(vrow, lang)
            if not a:
                results.append({"youtube_video_id": yt, "error": {"code": "NOT_FOUND", "message": "video not found"}})
                continue

        used_video_internal_ids.append(vrow.get("id"))
        used_asset_ids.append(a.get("id"))

        captions = a.get("payload", {}).get("captions") if isinstance(a.get("payload"), dict) else None
        if not isinstance(captions, list):
            captions = []

        # Apply time filtering
        def _in_range(cap):
            tt = cap.get("t")
            if not isinstance(tt, (int, float)):
                return False
            if startSeconds is not None and tt < startSeconds:
                return False
            if endSeconds is not None and tt > endSeconds:
                return False
            return True

        filtered_caps = [c for c in captions if isinstance(c, dict) and _in_range(c)]

        # Search
        matches = []
        if query_s is not None:
            q = query_s if caseSensitive_b else query_s.lower()
            for c in filtered_caps:
                txt = c.get("text") if isinstance(c.get("text"), str) else ""
                hay = txt if caseSensitive_b else txt.lower()
                if q in hay:
                    matches.append(c)
                    if len(matches) >= maxMatches_n:
                        break
        else:
            matches = filtered_caps

        if format_v == "plain":
            lines = []
            for c in matches:
                txt = c.get("text") if isinstance(c.get("text"), str) else ""
                if includeTimestamps_b:
                    tsec = c.get("t") if isinstance(c.get("t"), (int, float)) else 0
                    lines.append(f"[{tsec:.3f}] {txt}".rstrip())
                else:
                    lines.append(txt)
            out = "\n".join([ln for ln in lines if ln is not None])
            results.append({
                "youtube_video_id": yt,
                "video_id": vrow.get("id"),
                "language": lang,
                "asset_id": a.get("id"),
                "format": "plain",
                "match_count": len(matches) if query_s is not None else None,
                "text": out
            })
        else:
            # segments by segmentDurationSeconds
            segs = []
            if matches:
                start_t = matches[0].get("t") if isinstance(matches[0].get("t"), (int, float)) else 0.0
            else:
                start_t = startSeconds if startSeconds is not None else 0.0
            bucket = {}
            for c in matches:
                tt = c.get("t") if isinstance(c.get("t"), (int, float)) else None
                if tt is None:
                    continue
                idx = int(math.floor((tt - start_t) / float(segdur))) if segdur > 0 else 0
                bucket.setdefault(idx, []).append(c)
            for idx in sorted(bucket.keys()):
                caps = bucket[idx]
                seg_start = start_t + idx * float(segdur)
                seg_end = seg_start + float(segdur)
                lines = []
                for c in caps:
                    txt = c.get("text") if isinstance(c.get("text"), str) else ""
                    if includeTimestamps_b:
                        tsec = c.get("t") if isinstance(c.get("t"), (int, float)) else 0
                        lines.append({"t": tsec, "text": txt})
                    else:
                        lines.append({"text": txt})
                segs.append({"index": idx, "start": seg_start, "end": seg_end, "lines": lines})
            results.append({
                "youtube_video_id": yt,
                "video_id": vrow.get("id"),
                "language": lang,
                "asset_id": a.get("id"),
                "format": "segments",
                "segmentDurationSeconds": segdur,
                "match_count": len(matches) if query_s is not None else None,
                "segments": segs
            })

    # complete run
    run["status"] = "succeeded"
    fin = datetime.datetime.utcnow().replace(microsecond=0)
    run["finished_at"] = _iso(fin)
    run["updated_at"] = run["finished_at"]
    run["youtube_units_used"] = est_units
    run["cache_hit"] = cache_hit_all and (not forceRefresh_b)
    run["response_ref"] = {"videos": [vid for vid in used_video_internal_ids if vid], "assets": [aid for aid in used_asset_ids if aid]}
    _save("query_runs.json", query_runs)

    client["last_used_at"] = _iso(fin)
    client["updated_at"] = client["last_used_at"]
    _save("api_clients.json", api_clients)

    return {"data": {"results": results}, "meta": {"query_run_id": run_id, "latency_ms": int((time.time() - t0) * 1000)}}

def get_key_moments(videoId, language=None, maxMoments=None, minMomentDurationSeconds=None, forceRefresh=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0205000" if __import__("os").path.isdir("./environment_mix/0205000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _norm_lang(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "__INVALID__"
        v = s.strip()
        if not v or not (2 <= len(v) <= 16) or not re.fullmatch(r"[A-Za-z0-9-]+", v):
            return "__INVALID__"
        return v.lower()

    def _stable_fingerprint(obj):
        def _norm(x):
            if isinstance(x, dict):
                return {k: _norm(x[k]) for k in sorted(x)}
            if isinstance(x, list):
                return [_norm(v) for v in x]
            if isinstance(x, float):
                return float(f"{x:.6f}")
            return x
        b = json.dumps(_norm(obj), sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24]}"

    def _pick_active_client(clients):
        actives = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not actives:
            return None
        actives.sort(key=lambda c: _parse_iso(c.get("last_used_at")) or datetime.datetime.min, reverse=True)
        return actives[0]

    def _pick_any_client(clients):
        rows = [c for c in clients if isinstance(c, dict) and c.get("id")]
        if not rows:
            return None
        rows.sort(key=lambda c: _parse_iso(c.get("last_used_at")) or _parse_iso(c.get("updated_at")) or _parse_iso(c.get("created_at")) or datetime.datetime.min, reverse=True)
        return rows[0]

    def _count_today(runs, client_id):
        day = now.strftime("%Y-%m-%d")
        reqs = 0
        units = 0
        for r in runs:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            ca = r.get("created_at")
            if not isinstance(ca, str) or len(ca) < 10 or ca[:10] != day:
                continue
            reqs += 1
            try:
                units += max(0, int(r.get("youtube_units_used") or 0))
            except (TypeError, ValueError):
                pass
        return reqs, units

    # Validate
    if videoId is None or not isinstance(videoId, str) or not videoId.strip():
        return _err("VALIDATION_ERROR", "videoId is required and must be a non-empty string.", rule="videoId required")

    lang = _norm_lang(language)
    if lang == "__INVALID__":
        return _err("VALIDATION_ERROR", "language is malformed; expected 2-16 chars of letters/digits/hyphen.", rule="language format")

    if maxMoments is not None:
        if not isinstance(maxMoments, int):
            return _err("VALIDATION_ERROR", "maxMoments must be an integer.", rule="maxMoments type")
        if maxMoments < 1 or maxMoments > 50:
            return _err("VALIDATION_ERROR", "maxMoments must be within [1, 50].", rule="maxMoments range")
    if maxMoments is None:
        maxMoments = 10  # service default
    # tool schema says integer; calls may send float (audit used float for minMomentDurationSeconds). Accept and coerce.
    if minMomentDurationSeconds is not None:
        if not isinstance(minMomentDurationSeconds, (int, float)):
            return _err("VALIDATION_ERROR", "minMomentDurationSeconds must be a number.", rule="minMomentDurationSeconds type")
        if minMomentDurationSeconds < 5 or minMomentDurationSeconds > 1800:
            return _err("VALIDATION_ERROR", "minMomentDurationSeconds must be within [5, 1800].", rule="minMomentDurationSeconds range")
    if minMomentDurationSeconds is None:
        minMomentDurationSeconds = 10

    if forceRefresh is not None and not isinstance(forceRefresh, bool):
        return _err("VALIDATION_ERROR", "forceRefresh must be a boolean.", rule="forceRefresh type")

    clients = _load("api_clients.json")
    client = _pick_active_client(clients)

    runs = _load("query_runs.json")
    now_iso = _now_iso()
    normalized = {"language": None, "maxMoments": maxMoments, "minMomentDurationSeconds": float(minMomentDurationSeconds)}
    params = {
        "videoId": videoId.strip(),
        "language": language,
        "maxMoments": maxMoments,
        "minMomentDurationSeconds": float(minMomentDurationSeconds),
        "forceRefresh": bool(forceRefresh) if forceRefresh is not None else False,
        "normalized": normalized
    }
    fp = _stable_fingerprint({"tool": "get-key-moments", "params": {"videoId": videoId.strip(), **params["normalized"]}})
    qid = _new_id("ytqr")

    if not client:
        c_any = _pick_any_client(clients)
        if c_any:
            runs.append({
                "id": qid,
                "client_id": c_any["id"],
                "tool_name": "get-key-moments",
                "status": "failed",
                "request_fingerprint": fp,
                "parameters": params,
                "response_ref": None,
                "youtube_units_used": 0,
                "cache_hit": False,
                "error_message": "client_not_active",
                "started_at": now_iso,
                "finished_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso
            })
            _save("query_runs.json", runs)
        return _err("UNAUTHORIZED", "No active API client available for this request.")

    runs.append({
        "id": qid,
        "client_id": client["id"],
