            "title": f"Video {videoId.strip()}",
            "description": None,
            "published_at": None,
            "duration_seconds": None,
            "category_id": None,
            "default_language": lang or "en",
            "default_audio_language": None,
            "tags": None,
            "thumbnail_url": None,
            "status": "active",
            "view_count": None,
            "like_count": None,
            "comment_count": None,
            "stats_as_of": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        videos.append(video)
        _save("videos.json", videos)

    eff_lang = lang or (video.get("default_language") if isinstance(video.get("default_language"), str) and video.get("default_language").strip() else "en")
    normalized["language"] = eff_lang
    params["normalized"] = normalized

    # Find or build key_moments asset keyed by (video_id, language, maxMoments)
    assets = _load("video_text_assets.json")

    def _asset_key_match(a):
        if not isinstance(a, dict):
            return False
        if a.get("video_id") != video.get("id"):
            return False
        if a.get("asset_type") != "key_moments":
            return False
        if (a.get("language") or "").lower() != eff_lang.lower():
            return False
        if a.get("status") != "ready":
            return False
        p = a.get("payload")
        if not isinstance(p, dict):
            return False
        mm = p.get("maxMoments")
        try:
            mm = int(mm) if mm is not None else None
        except (TypeError, ValueError):
            mm = None
        return mm == int(maxMoments)

    existing = []
    for a in assets:
        if _asset_key_match(a):
            try:
                ver = int(a.get("version") or 0)
            except (TypeError, ValueError):
                ver = 0
            existing.append((ver, _parse_iso(a.get("updated_at")) or _parse_iso(a.get("created_at")) or datetime.datetime.min, a))
    existing.sort(key=lambda t: (t[0], t[1]), reverse=True)
    chosen = existing[0][2] if (existing and not params["forceRefresh"]) else None
    cache_hit = bool(chosen)

    if not chosen:
        # ensure transcript exists (best-effort) -> look for transcript_track ready; otherwise fail with asset/audit
        transcript = None
        for a in assets:
            if isinstance(a, dict) and a.get("video_id") == video.get("id") and a.get("asset_type") == "transcript_track" and (a.get("language") or "").lower() == eff_lang.lower() and a.get("status") == "ready":
                transcript = a
                break
        if not transcript:
            fin = _now_iso()
            runs = _load("query_runs.json")
            for r in runs:
                if isinstance(r, dict) and r.get("id") == qid:
                    r["status"] = "failed"
