                    r["finished_at"] = fin
                    r["updated_at"] = fin
                    break
            _save("query_runs.json", runs)
            return _err("NOT_FOUND", "No transcript available to derive key moments.", rule="transcript_track required")

        # next version for key_moments (video,type,lang)
        max_ver = 0
        for a in assets:
            if isinstance(a, dict) and a.get("video_id") == video.get("id") and a.get("asset_type") == "key_moments" and (a.get("language") or "").lower() == eff_lang.lower():
                try:
                    max_ver = max(max_ver, int(a.get("version") or 0))
                except (TypeError, ValueError):
                    pass
        ver = max(1, max_ver + 1)

        # derive simple moments: chunk transcript into evenly spaced segments with scores
        captions = transcript.get("payload", {}).get("captions")
        if not isinstance(captions, list):
            captions = []
        # Determine time bounds from captions
        times = []
        for c in captions:
            if isinstance(c, dict) and isinstance(c.get("t"), (int, float)):
                times.append(float(c["t"]))
        start_t = min(times) if times else 0.0
        end_t = max(times) if times else max(start_t, start_t + float(minMomentDurationSeconds) * maxMoments)
        total = max(0.0, end_t - start_t)
        seg = max(float(minMomentDurationSeconds), (total / maxMoments) if maxMoments else float(minMomentDurationSeconds))
        moments = []
        for i in range(int(maxMoments)):
            s = start_t + i * seg
            e = s + seg
            if e - s < float(minMomentDurationSeconds):
                e = s + float(minMomentDurationSeconds)
            moments.append({"start": float(s), "end": float(e), "title": None, "summary": None, "score": float(maxMoments - i) / float(maxMoments)})

        asset_id = _new_id("ytta")
        chosen = {
            "id": asset_id,
            "video_id": video.get("id"),
            "asset_type": "key_moments",
            "language": eff_lang,
            "source": "derived",
            "status": "ready",
            "version": ver,
            "expires_at": None,
            "payload": {"moments": moments, "maxMoments": int(maxMoments), "minMomentDurationSeconds": float(minMomentDurationSeconds)},
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        assets.append(chosen)
        _save("video_text_assets.json", assets)

    fin = _now_iso()
    runs = _load("query_runs.json")
    for r in runs:
        if isinstance(r, dict) and r.get("id") == qid:
            r["status"] = "succeeded"
            r["parameters"] = params
            r["response_ref"] = {"video": video.get("id"), "assets": [chosen.get("id")]}
            r["youtube_units_used"] = 0
            r["cache_hit"] = cache_hit
            r["finished_at"] = fin
            r["updated_at"] = fin
            break
    _save("query_runs.json", runs)

    clients = _load("api_clients.json")
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client.get("id"):
            c["last_used_at"] = fin
            c["updated_at"] = fin
            break
    _save("api_clients.json", clients)

    return {
        "videoId": videoId.strip(),
        "language": eff_lang,
        "asset": {k: chosen.get(k) for k in ("id", "asset_type", "language", "source", "status", "version", "created_at", "updated_at")},
        "moments": (chosen.get("payload") or {}).get("moments") if isinstance(chosen.get("payload"), dict) else [],
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def get_segmented_transcript(videoId, language=None, segmentCount=None, startSeconds=None, endSeconds=None, forceRefresh=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, re, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0205000" if __import__("os").path.isdir("./environment_mix/0205000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    DEFAULT_SEGMENTS = 12

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _norm_lang(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "__INVALID__"
        v = s.strip()
        if not v or not (2 <= len(v) <= 16) or not re.fullmatch(r"[A-Za-z0-9-]+", v):
            return "__INVALID__"
        return v.lower()

    def _stable_fingerprint(obj):
        def _norm(x):
            if isinstance(x, dict):
                return {k: _norm(x[k]) for k in sorted(x)}
            if isinstance(x, list):
                return [_norm(v) for v in x]
            if isinstance(x, float):
                return float(f"{x:.6f}")
            return x
        b = json.dumps(_norm(obj), sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24]}"

    def _pick_active_client(clients):
        actives = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not actives:
            return None
        actives.sort(key=lambda c: _parse_iso(c.get("last_used_at")) or datetime.datetime.min, reverse=True)
        return actives[0]

    def _pick_any_client(clients):
        rows = [c for c in clients if isinstance(c, dict) and c.get("id")]
        if not rows:
            return None
        rows.sort(key=lambda c: _parse_iso(c.get("last_used_at")) or _parse_iso(c.get("updated_at")) or _parse_iso(c.get("created_at")) or datetime.datetime.min, reverse=True)
        return rows[0]

    def _count_today(runs, client_id):
        day = now.strftime("%Y-%m-%d")
        reqs = 0
        units = 0
        for r in runs:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            ca = r.get("created_at")
            if not isinstance(ca, str) or len(ca) < 10 or ca[:10] != day:
                continue
            reqs += 1
            try:
                units += max(0, int(r.get("youtube_units_used") or 0))
            except (TypeError, ValueError):
                pass
        return reqs, units

    # Validate
    if videoId is None or not isinstance(videoId, str) or not videoId.strip():
        return _err("VALIDATION_ERROR", "videoId is required and must be a non-empty string.", rule="videoId required")
    lang = _norm_lang(language)
    if lang == "__INVALID__":
        return _err("VALIDATION_ERROR", "language is malformed; expected 2-16 chars of letters/digits/hyphen.", rule="language format")

    if segmentCount is not None:
        if not isinstance(segmentCount, int):
            return _err("VALIDATION_ERROR", "segmentCount must be an integer.", rule="segmentCount type")
        if segmentCount < 1 or segmentCount > 200:
            return _err("VALIDATION_ERROR", "segmentCount must be within [1, 200].", rule="segmentCount range")
    if segmentCount is None:
        segmentCount = DEFAULT_SEGMENTS

    # Accept numbers; do not require startSeconds <= endSeconds (audit had end < start); normalize by swapping.
    if startSeconds is not None and not isinstance(startSeconds, (int, float)):
        return _err("VALIDATION_ERROR", "startSeconds must be a number.", rule="startSeconds type")
    if endSeconds is not None and not isinstance(endSeconds, (int, float)):
        return _err("VALIDATION_ERROR", "endSeconds must be a number.", rule="endSeconds type")
    if startSeconds is not None and startSeconds < 0:
        return _err("VALIDATION_ERROR", "startSeconds must be >= 0.", rule="startSeconds minimum")
    if endSeconds is not None and endSeconds < 0:
        return _err("VALIDATION_ERROR", "endSeconds must be >= 0.", rule="endSeconds minimum")

    s0 = float(startSeconds) if startSeconds is not None else 0.0
    e0 = float(endSeconds) if endSeconds is not None else None
    if e0 is not None and e0 < s0:
        s0, e0 = e0, s0  # normalize instead of rejecting

    if forceRefresh is not None and not isinstance(forceRefresh, bool):
        return _err("VALIDATION_ERROR", "forceRefresh must be a boolean.", rule="forceRefresh type")

    clients = _load("api_clients.json")
    client = _pick_active_client(clients)
    runs = _load("query_runs.json")
    now_iso = _now_iso()
    normalized = {"language": None, "segmentCount": int(segmentCount), "startSeconds": float(s0), "endSeconds": float(e0) if e0 is not None else None}
    params = {
        "videoId": videoId.strip(),
        "language": language,
        "segmentCount": segmentCount,
        "startSeconds": startSeconds,
        "endSeconds": endSeconds,
        "forceRefresh": bool(forceRefresh) if forceRefresh is not None else False,
        "normalized": normalized
    }
    fp = _stable_fingerprint({"tool": "get-segmented-transcript", "params": {"videoId": videoId.strip(), **normalized}})
