                "cache_hit": False,
                "error_message": "client_not_active",
                "started_at": now_iso,
                "finished_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso
            })
            _save("query_runs.json", runs)
        return _err("UNAUTHORIZED", "No active API client available for this request.")

    runs.append({
        "id": qid,
        "client_id": client["id"],
        "tool_name": "get-segmented-transcript",
        "status": "queued",
        "request_fingerprint": fp,
        "parameters": params,
        "response_ref": None,
        "youtube_units_used": 0,
        "cache_hit": False,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("query_runs.json", runs)

    reqs_today, _ = _count_today(_load("query_runs.json"), client["id"])
    try:
        req_quota = int(client.get("daily_request_quota"))
    except (TypeError, ValueError):
        req_quota = 0
    if req_quota >= 0 and reqs_today > req_quota:
        fin = _now_iso()
        runs = _load("query_runs.json")
        for r in runs:
            if isinstance(r, dict) and r.get("id") == qid:
                r["status"] = "failed"
                r["error_message"] = "quota_exceeded_requests_daily"
                r["started_at"] = r.get("started_at") or now_iso
                r["finished_at"] = fin
                r["updated_at"] = fin
                break
        _save("query_runs.json", runs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", rule="daily_request_quota")

    # running
    runs = _load("query_runs.json")
    for r in runs:
        if isinstance(r, dict) and r.get("id") == qid:
            r["status"] = "running"
            r["started_at"] = now_iso
            r["updated_at"] = now_iso
            break
    _save("query_runs.json", runs)

    # Resolve or discover video
    videos = _load("videos.json")
    video = None
    for v in videos:
        if isinstance(v, dict) and v.get("youtube_video_id") == videoId.strip():
            video = v
            break
    if video is None:
        channels = _load("channels.json")
        cand = [c for c in channels if isinstance(c, dict) and c.get("status") in ("active", "unavailable") and c.get("id")]
        if not cand:
            cand = [c for c in channels if isinstance(c, dict) and c.get("id")]
        if not cand:
            fin = _now_iso()
            runs = _load("query_runs.json")
            for r in runs:
                if isinstance(r, dict) and r.get("id") == qid:
                    r["status"] = "failed"
                    r["error_message"] = "video_not_found_no_channel_context"
                    r["finished_at"] = fin
                    r["updated_at"] = fin
                    break
            _save("query_runs.json", runs)
            return _err("NOT_FOUND", "video not found", rule="videoId must resolve to a known video")
        ch = cand[0]
        video = {
            "id": _new_id("ytv"),
            "youtube_video_id": videoId.strip(),
            "channel_id": ch["id"],
            "title": f"Video {videoId.strip()}",
            "description": None,
            "published_at": None,
            "duration_seconds": None,
            "category_id": None,
            "default_language": lang or "en",
            "default_audio_language": None,
            "tags": None,
            "thumbnail_url": None,
            "status": "active",
