        captions = transcript.get("payload", {}).get("captions")
        if not isinstance(captions, list):
            captions = []

        # derive segments in [s0,e0] or to end of captions
        times = [float(c.get("t")) for c in captions if isinstance(c, dict) and isinstance(c.get("t"), (int, float))]
        cap_start = min(times) if times else 0.0
