        segments = []
        for i in range(int(segmentCount)):
            s = seg_start + i * step
            e = seg_end if i == int(segmentCount) - 1 else (seg_start + (i + 1) * step)
            seg_caps = []
            for c in captions:
                if not isinstance(c, dict):
                    continue
                t = c.get("t")
                if not isinstance(t, (int, float)):
                    continue
                tt = float(t)
                if tt < s or tt >= e:
                    continue
                seg_caps.append(c)
            segments.append({"index": i, "start": float(s), "end": float(e), "captions": seg_caps})

        # next version for segmented_transcript
        max_ver = 0
        for a in assets:
            if isinstance(a, dict) and a.get("video_id") == video.get("id") and a.get("asset_type") == "segmented_transcript" and (a.get("language") or "").lower() == eff_lang.lower():
                try:
                    max_ver = max(max_ver, int(a.get("version") or 0))
                except (TypeError, ValueError):
                    pass
        ver = max(1, max_ver + 1)

        chosen = {
            "id": _new_id("ytta"),
            "video_id": video.get("id"),
            "asset_type": "segmented_transcript",
            "language": eff_lang,
            "source": "derived",
            "status": "ready",
            "version": ver,
            "expires_at": None,
            "payload": {"segments": segments, "segmentCount": int(segmentCount), "startSeconds": float(seg_start), "endSeconds": float(seg_end)},
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        assets.append(chosen)
        _save("video_text_assets.json", assets)

    fin = _now_iso()
    runs = _load("query_runs.json")
    for r in runs:
        if isinstance(r, dict) and r.get("id") == qid:
            r["status"] = "succeeded"
            r["parameters"] = params
            r["response_ref"] = {"video": video.get("id"), "assets": [chosen.get("id")]}
            r["youtube_units_used"] = 0
            r["cache_hit"] = cache_hit
            r["finished_at"] = fin
            r["updated_at"] = fin
            break
    _save("query_runs.json", runs)

    clients = _load("api_clients.json")
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client.get("id"):
            c["last_used_at"] = fin
            c["updated_at"] = fin
            break
    _save("api_clients.json", clients)

    payload = chosen.get("payload") if isinstance(chosen.get("payload"), dict) else {}
    return {
        "videoId": videoId.strip(),
        "language": eff_lang,
        "segmentCount": int(segmentCount),
        "asset": {k: chosen.get(k) for k in ("id", "asset_type", "language", "source", "status", "version", "created_at", "updated_at")},
        "segments": payload.get("segments") if isinstance(payload.get("segments"), list) else [],
        "range": {"startSeconds": payload.get("startSeconds"), "endSeconds": payload.get("endSeconds")},
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }
